pub const ParsedUrl = struct {
    scheme: []const u8,
    host: []const u8,
    port: ?u16,
    path: []const u8,
    query: []const u8,
    fragment: []const u8,

    pub fn deinit(self: *ParsedUrl, allocator: Allocator) void {
        allocator.free(self.scheme);
        allocator.free(self.host);
        allocator.free(self.path);
        allocator.free(self.query);
        allocator.free(self.fragment);
    }
};

pub fn parseUrl(allocator: Allocator, raw_url: []const u8) !ParsedUrl {
    var scheme: []const u8 = "";
    var host: []const u8 = "";
    var port: ?u16 = null;
    var path: []const u8 = "";
    var query: []const u8 = "";
    var fragment: []const u8 = "";

    var rest = raw_url;
    if (std.mem.indexOf(u8, rest, "://")) |idx| {
        scheme = rest[0..idx];
        rest = rest[idx + 3 ..];
    }

    if (std.mem.indexOfScalar(u8, rest, '#')) |idx| {
        fragment = rest[idx + 1 ..];
        rest = rest[0..idx];
    }

    if (std.mem.indexOfScalar(u8, rest, '?')) |idx| {
        query = rest[idx + 1 ..];
        rest = rest[0..idx];
    }

    if (std.mem.indexOfScalar(u8, rest, '/')) |idx| {
        host = rest[0..idx];
        path = rest[idx..];
    } else {
        host = rest;
        path = "/";
    }

    if (std.mem.indexOfScalar(u8, host, ':')) |idx| {
        const port_str = host[idx + 1 ..];
        port = std.fmt.parseInt(u16, port_str, 10) catch null;
        host = host[0..idx];
    }

    return ParsedUrl{
        .scheme = try allocator.dupe(u8, scheme),
        .host = try allocator.dupe(u8, host),
        .port = port,
        .path = try allocator.dupe(u8, path),
        .query = try allocator.dupe(u8, query),
        .fragment = try allocator.dupe(u8, fragment),
    };
}

pub fn canonicalizeUrl(allocator: Allocator, raw_url: []const u8) ![]u8 {
    var parsed = try parseUrl(allocator, raw_url);
    defer parsed.deinit(allocator);

    var lower_scheme = try allocator.dupe(u8, parsed.scheme);
    defer allocator.free(lower_scheme);
    for (lower_scheme) |*c| c.* = std.ascii.toLower(c.*);

    var lower_host = try allocator.dupe(u8, parsed.host);
    defer allocator.free(lower_host);
    for (lower_host) |*c| c.* = std.ascii.toLower(c.*);

    var clean_path = parsed.path;
    if (clean_path.len > 1 and clean_path[clean_path.len - 1] == '/') {
        clean_path = clean_path[0 .. clean_path.len - 1];
    }

    if (parsed.query.len > 0) {
        return std.fmt.allocPrint(allocator, "{s}://{s}{s}?{s}", .{ lower_scheme, lower_host, clean_path, parsed.query });
    } else {
        return std.fmt.allocPrint(allocator, "{s}://{s}{s}", .{ lower_scheme, lower_host, clean_path });
    }
}

pub fn domainFromUrl(allocator: Allocator, raw_url: []const u8) ![]u8 {
    var parsed = try parseUrl(allocator, raw_url);
    defer parsed.deinit(allocator);
    var host = try allocator.dupe(u8, parsed.host);
    for (host) |*c| c.* = std.ascii.toLower(c.*);
    return host;
}

pub fn looksLikeImageUrl(url: []const u8) bool {
    const extensions = [_][]const u8{
        ".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp", ".tiff", ".svg", ".avif", ".ico",
    };
    var lower_buf: [512]u8 = undefined;
    const len = @min(url.len, lower_buf.len);
    for (url[0..len], 0..) |c, i| {
        lower_buf[i] = std.ascii.toLower(c);
    }
    const lower = lower_buf[0..len];
    for (extensions) |ext| {
        if (std.mem.indexOf(u8, lower, ext) != null) return true;
    }
    return false;
}

