pub fn hammingDistance(a: []const u8, b: []const u8) usize {
    var dist: usize = 0;
    const min_len = @min(a.len, b.len);
    for (a[0..min_len], b[0..min_len]) |c1, c2| {
        const v1 = std.fmt.parseInt(u8, &[_]u8{c1}, 16) catch 0;
        const v2 = std.fmt.parseInt(u8, &[_]u8{c2}, 16) catch 0;
        dist += @popCount(v1 ^ v2);
    }
    if (a.len != b.len) {
        dist += (@max(a.len, b.len) - min_len) * 4;
    }
    return dist;
}

pub fn hammingSimilarity(a: []const u8, b: []const u8) f64 {
    const bit_len = @max(a.len, b.len) * 4;
    if (bit_len == 0) return 1.0;
    const dist = hammingDistance(a, b);
    return 1.0 - (@as(f64, @floatFromInt(dist)) / @as(f64, @floatFromInt(bit_len)));
}

pub fn cosineSimilarity(v1: []const f32, v2: []const f32) f32 {
    if (v1.len == 0 or v2.len == 0 or v1.len != v2.len) return 0.0;
    var dot: f32 = 0.0;
    var norm1: f32 = 0.0;
    var norm2: f32 = 0.0;
    for (v1, v2) |x, y| {
        dot += x * y;
        norm1 += x * x;
        norm2 += y * y;
    }
    if (norm1 <= 0.0 or norm2 <= 0.0) return 0.0;
    return dot / (@sqrt(norm1) * @sqrt(norm2));
}

pub fn colorHistogram(allocator: Allocator, image_bytes: []const u8) ![]f32 {
    const bins = try allocator.alloc(f32, 64);
    @memset(bins, 0.0);
    if (image_bytes.len == 0) return bins;

    for (image_bytes) |b| {
        const idx = b % 64;
        bins[idx] += 1.0;
    }

    const total = @as(f32, @floatFromInt(image_bytes.len));
    for (bins) |*b| {
        b.* /= total;
    }
    return bins;
}

pub fn colorHistSimilarity(h1: []const f32, h2: []const f32) f64 {
    if (h1.len == 0 or h2.len == 0 or h1.len != h2.len) return 0.0;
    var sum_min: f64 = 0.0;
    for (h1, h2) |v1, v2| {
        sum_min += @min(v1, v2);
    }
    return sum_min;
}

pub fn dimensionSimilarity(w1: u32, h1: u32, w2: u32, h2: u32) f64 {
    if (w1 == 0 or h1 == 0 or w2 == 0 or h2 == 0) return 0.0;
    const ar1 = @as(f64, @floatFromInt(w1)) / @as(f64, @floatFromInt(h1));
    const ar2 = @as(f64, @floatFromInt(w2)) / @as(f64, @floatFromInt(h2));
    const ar_ratio = if (ar1 > ar2) ar2 / ar1 else ar1 / ar2;

    const area1 = @as(f64, @floatFromInt(w1 * h1));
    const area2 = @as(f64, @floatFromInt(w2 * h2));
    const area_ratio = if (area1 > area2) area2 / area1 else area1 / area2;

    return (ar_ratio * 0.6) + (area_ratio * 0.4);
}

