pub fn extractPageData(allocator: Allocator, base_url: []const u8, html_content: []const u8) !ExtractedPageData {
    var images = ArrayList([]const u8).init(allocator);
    errdefer {
        for (images.items) |item| allocator.free(item);
        images.deinit();
    }
    var links = ArrayList([]const u8).init(allocator);
    errdefer {
        for (links.items) |item| allocator.free(item);
        links.deinit();
    }

    var pos: usize = 0;
    var title: []const u8 = "";

    if (std.mem.indexOf(u8, html_content, "<title>")) |t_start| {
        if (std.mem.indexOfPos(u8, html_content, t_start, "</title>")) |t_end| {
            title = try allocator.dupe(u8, html_content[t_start + 7 .. t_end]);
        }
    }
    if (title.len == 0) {
        title = try allocator.dupe(u8, "");
    }

    while (pos < html_content.len) {
        const src_idx = std.mem.indexOfPos(u8, html_content, pos, "src=\"");
        const href_idx = std.mem.indexOfPos(u8, html_content, pos, "href=\"");

        if (src_idx == null and href_idx == null) break;

        if (src_idx != null and (href_idx == null or src_idx.? < href_idx.?)) {
            const start = src_idx.? + 5;
            if (std.mem.indexOfPos(u8, html_content, start, "\"")) |end| {
                const raw_ref = html_content[start..end];
                if (looksLikeImageUrl(raw_ref)) {
                    const resolved = if (std.mem.startsWith(u8, raw_ref, "http://") or std.mem.startsWith(u8, raw_ref, "https://"))
                        try allocator.dupe(u8, raw_ref)
                    else
                        try std.fmt.allocPrint(allocator, "{s}/{s}", .{ base_url, raw_ref });
                    try images.append(resolved);
                }
                pos = end + 1;
            } else {
                break;
            }
        } else if (href_idx != null) {
            const start = href_idx.? + 6;
            if (std.mem.indexOfPos(u8, html_content, start, "\"")) |end| {
                const raw_ref = html_content[start..end];
                const resolved = if (std.mem.startsWith(u8, raw_ref, "http://") or std.mem.startsWith(u8, raw_ref, "https://"))
                    try allocator.dupe(u8, raw_ref)
                else
                    try std.fmt.allocPrint(allocator, "{s}/{s}", .{ base_url, raw_ref });
                if (looksLikeImageUrl(raw_ref)) {
                    try images.append(resolved);
                } else {
                    try links.append(resolved);
                }
                pos = end + 1;
            } else {
                break;
            }
        }
    }

    return ExtractedPageData{
        .title = title,
        .image_urls = try images.toOwnedSlice(),
        .page_urls = try links.toOwnedSlice(),
    };
}

pub const RobotsRules = struct {
    disallowed_paths: ArrayList([]const u8),
    allocator: Allocator,

    pub fn init(allocator: Allocator) RobotsRules {
        return RobotsRules{
            .disallowed_paths = ArrayList([]const u8).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *RobotsRules) void {
        for (self.disallowed_paths.items) |path| {
            self.allocator.free(path);
        }
        self.disallowed_paths.deinit();
    }

    pub fn parse(self: *RobotsRules, content: []const u8) !void {
        var lines = std.mem.splitScalar(u8, content, '\n');
        var applies = true;
        while (lines.next()) |line| {
            const trimmed = std.mem.trim(u8, line, " \t\r");
            if (trimmed.len == 0 or trimmed[0] == '#') continue;

            if (std.ascii.startsWithIgnoreCase(trimmed, "user-agent:")) {
                const agent = std.mem.trim(u8, trimmed[11..], " \t");
                applies = std.mem.eql(u8, agent, "*") or std.ascii.eqlIgnoreCase(agent, "bot");
            } else if (applies and std.ascii.startsWithIgnoreCase(trimmed, "disallow:")) {
                const path = std.mem.trim(u8, trimmed[9..], " \t");
                if (path.len > 0) {
                    try self.disallowed_paths.append(try self.allocator.dupe(u8, path));
                }
            }
        }
    }

    pub fn isAllowed(self: *const RobotsRules, path: []const u8) bool {
        for (self.disallowed_paths.items) |disallowed| {
            if (std.mem.startsWith(u8, path, disallowed)) {
                return false;
            }
        }
        return true;
    }
};

