        return EngineStore{
            .assets = ArrayList(AssetRecord).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EngineStore) void {
        for (self.assets.items) |*a| {
            a.deinit(self.allocator);
        }
        self.assets.deinit();
    }

    pub fn insert(self: *EngineStore, record: AssetRecord) !void {
        try self.assets.append(record);
    }

    pub fn searchByVector(self: *EngineStore, allocator: Allocator, query_vec: []const f32, limit: usize) ![]AssetRecord {
        var matches = ArrayList(AssetRecord).init(allocator);
        for (self.assets.items) |item| {
            if (matches.items.len >= limit) break;
            const score = cosineSimilarity(query_vec, item.embedding);
            if (score > 0.1) {
                try matches.append(item);
            }
        }
        return matches.toOwnedSlice();
    }
};

pub const HttpClientWrapper = struct {
    allocator: Allocator,

    pub fn init(allocator: Allocator) HttpClientWrapper {
        return HttpClientWrapper{ .allocator = allocator };
    }

    pub fn fetch(self: *HttpClientWrapper, target_url: []const u8) ![]u8 {
        var client: std.http.Client = .{ .allocator = self.allocator };
        defer client.deinit();

        var body_buffer = ArrayList(u8).init(self.allocator);
        defer body_buffer.deinit();

        const uri = try std.Uri.parse(target_url);
        var req = try client.open(.GET, uri, .{
            .server_header_buffer = try self.allocator.alloc(u8, 16384),
        });
        defer {
            self.allocator.free(req.server_header_buffer);
            req.deinit();
        }

        try req.send();
        try req.finish();
        try req.wait();

        var reader = req.reader();
        var buf: [4096]u8 = undefined;
        while (true) {
            const read_bytes = try reader.read(&buf);
            if (read_bytes == 0) break;
            try body_buffer.appendSlice(buf[0..read_bytes]);
        }

        return body_buffer.toOwnedSlice();
    }
};

